import{c as e,Q as a,j as i,m as r}from"./chunks/framework.DOi4mjdC.js";const s="/assets/%E8%AE%A1%E7%AE%97%E6%8B%96%E5%B0%BE%E7%A4%BA%E6%84%8F%E5%9B%BE.BEClJe_F.png",o="/assets/%E6%A0%B8%E9%97%B4%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE.CQWSbLP3.png",B=JSON.parse('{"title":"核间负载均衡","description":"","frontmatter":{},"headers":[{"level":1,"title":"核间负载均衡","slug":"核间负载均衡"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/Tiling策略/核间负载均衡.md","filePath":"guide/算子实践参考/SIMD算子性能优化/Tiling策略/核间负载均衡.md"}'),_={name:"guide/算子实践参考/SIMD算子性能优化/Tiling策略/核间负载均衡.md"};function n(p,t,l,E,c,g){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="核间负载均衡" tabindex="-1">核间负载均衡 <a class="header-anchor" href="#核间负载均衡" aria-label="Permalink to &quot;核间负载均衡&quot;">​</a></h1><p>【优先级】：中</p><p>【描述】AI处理器的物理核数是固定的，当L2 Cache切分之后，可能发生部分核有计算拖尾的情况，即每次所有核计算量除以每个核处理的数据量不能被核数整除，导致最后需要部分尾核来计算尾块数据。而在尾核计算时，部分核始终处于空闲状态，从而使得算子的整体性能变差。如<a href="#fig26395321518">图1</a>，假设总的数据量为TotalSize，L2 Cache切分之后分为两份TotalSize / 2，每个核每次的计算量为TotalSize / 2 / 25，即需要25个核进行处理，由于AI处理器的核数为20，因此每次计算时，1到5核的每个核需要多算一份数据，导致发生拖尾的情况。</p><p>【反例】</p><p><strong>图 1</strong> 计算拖尾示意图<br><img src="'+s+'" alt="" title="计算拖尾示意图"></p><p>【正例】</p><p>针对上述切分策略，调整拖尾核的位置后可以达到全局负载最优，如<a href="#fig133658471154">图2</a>所示。完成所有计算时，1到10核多一次数据块的计算，可以实现全局负载最优。</p><p><strong>图 2</strong> 核间负载均衡示意图<br><img src="'+o+'" alt="" title="核间负载均衡示意图"></p>',8)])])}const m=e(_,[["render",n]]);export{B as __pageData,m as default};
